INSERT INTO training_resources (title, category, content_type, content, video_url, author, duration_minutes, is_published, sport, tags) VALUES
('Beginner''s Guide to Athletics Training', 'Training Basics', 'GUIDE', 'Complete guide covering warm-up, technique drills, and cool-down for young athletes. Includes nutrition advice and recovery tips.', NULL, 'Coach Ramesh Kumar', 45, true, 'Athletics', ARRAY['beginner', 'warm-up', 'technique', 'nutrition']),
('Mental Strength for Athletes', 'Mental Health', 'ARTICLE', 'Understanding the importance of mental health in sports performance. Tips on handling pressure, staying motivated, and dealing with setbacks.', NULL, 'Dr. Priya Sharma', 20, true, NULL, ARRAY['mental health', 'motivation', 'pressure']),
('Nutrition Guide for Female Athletes', 'Nutrition', 'ARTICLE', 'Essential nutrition advice for girl athletes including iron requirements, protein intake, and maintaining energy balance during training.', NULL, 'Dr. Anjali Rao', 25, true, NULL, ARRAY['nutrition', 'iron', 'protein', 'energy']),
('Kabaddi Training Drills - Video Series', 'Training Basics', 'VIDEO', 'Step-by-step video tutorials for kabaddi skills including raiding technique, defending positions, and conditioning exercises.', 'https://training.shakthi.org/kabaddi-drills', 'Coach Sunil Kumar', 60, true, 'Kabaddi', ARRAY['kabaddi', 'raiding', 'defending', 'drills']),
('Injury Prevention Exercises', 'Exercise', 'EXERCISE', 'Daily routine of 15 exercises to prevent common sports injuries. Focus on knees, ankles, and shoulders.', NULL, 'Physio Arun Patel', 30, true, NULL, ARRAY['injury prevention', 'mobility', 'strength']),
('Yoga for Flexibility', 'Exercise', 'VIDEO', '10-minute yoga routine specifically designed for athletes. Improves flexibility and mental focus.', 'https://training.shakthi.org/yoga-flexibility', 'Yoga Instructor Meena Devi', 10, true, NULL, ARRAY['yoga', 'flexibility', 'mindfulness']),
('Badminton Grip and Stroke Basics', 'Training Basics', 'VIDEO', 'Master the fundamental grips and strokes in badminton. Beginner-friendly tutorial.', 'https://training.shakthi.org/badminton-basics', 'Coach Rajesh Singh', 35, true, 'Badminton', ARRAY['badminton', 'grip', 'stroke', 'beginner']),
('Wrestling Diet and Weight Management', 'Nutrition', 'ARTICLE', 'Safe weight management strategies for wrestlers. Importance of hydration and timing of meals.', NULL, 'Sports Nutritionist Kavita', 15, true, 'Wrestling', ARRAY['wrestling', 'diet', 'weight', 'nutrition']),
('Hockey Skills: Dribbling and Passing', 'Training Basics', 'VIDEO', 'Learn essential hockey dribbling techniques and passing drills for team play.', 'https://training.shakthi.org/hockey-skills', 'Coach Harpreet Singh', 40, true, 'Hockey', ARRAY['hockey', 'dribbling', 'passing', 'skills']),
('Recovery and Rest for Young Athletes', 'Mental Health', 'ARTICLE', 'Understanding the importance of rest days and recovery. Signs of overtraining and when to take a break.', NULL, 'Dr. Sunita Verma', 20, true, NULL, ARRAY['recovery', 'rest', 'overtraining', 'health']),
('Cricket Batting Techniques for Women', 'Training Basics', 'VIDEO', 'Master cover drives, pull shots, and defensive techniques. Specifically designed for women cricketers.', 'https://training.shakthi.org/cricket-batting', 'Coach Mithali Raj Academy', 50, true, 'Cricket', ARRAY['cricket', 'batting', 'technique', 'women']),
('Strength Training Without Gym', 'Exercise', 'VIDEO', 'Bodyweight exercises for building strength at home. No equipment needed.', 'https://training.shakthi.org/strength-home', 'Fitness Trainer Anita', 25, true, NULL, ARRAY['strength', 'home workout', 'bodyweight']),
('Kho-Kho Game Rules and Strategies', 'Training Basics', 'GUIDE', 'Complete rulebook and advanced strategies for kho-kho players and coaches.', NULL, 'KKFI Technical Committee', 30, true, 'Kho-Kho', ARRAY['kho-kho', 'rules', 'strategy', 'tactics']),
('Building Confidence in Sports', 'Mental Health', 'ARTICLE', 'Practical tips for building self-confidence as an athlete. Managing fearlessness vs anxiety.', NULL, 'Sports Psychologist Dr. Kaur', 15, true, NULL, ARRAY['confidence', 'mental health', 'anxiety']),
('Pre-Competition Routine Guide', 'Training Basics', 'ARTICLE', 'How to prepare mentally and physically before a competition. Night-before and morning-of routines.', NULL, 'Coach Sunil Kumar', 10, true, NULL, ARRAY['competition', 'routine', 'preparation', 'tips']);
